export function DragDemo({
  label = "{{label}}",
  dragging = {{dragging}},
  accent = "{{accent}}",
  rotation = {{rotation}},
}) {
  return (
    <div style={{ width: 280, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <div style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", color: "#241430aa", marginBottom: 8 }}>Backlog</div>
      <div draggable style={{ display: "flex", alignItems: "center", gap: 8, padding: "12px 14px", borderRadius: 10, background: "#FAF7F2",
        border: "1.5px solid " + accent, cursor: dragging ? "grabbing" : "grab", transition: "transform .12s, box-shadow .12s",
        transform: dragging ? "rotate(" + rotation + "deg) scale(1.03)" : "none",
        boxShadow: dragging ? "0 16px 30px rgba(36,20,48,.28)" : "0 2px 6px rgba(36,20,48,.1)" }}>
        <span style={{ color: accent, letterSpacing: -3, fontWeight: 700 }}>&#8942;&#8942;</span>{label}
      </div>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430aa" }}>{dragging ? "shown mid-drag: lifted, rotated " + rotation + "\u00b0, shadow deepens" : "rest state \u2014 drag the handle to move it"}</p>
    </div>
  );
}
